// Run clip plus a continuous circuit of the woodland trail.
let mixer, elapsed = 0;
function init() {
 const fox = this.getObjectByName('Fox');
 mixer = new THREE.AnimationMixer(fox);
 const clip = THREE.AnimationClip.findByName(fox.animations, 'Run') || fox.animations[0];
 if (clip) mixer.clipAction(clip).play();
}
function update(event) {
 const dt = Math.min(event.delta / 1000, 0.1);
 elapsed += dt;
 mixer.update(dt);
 const angle = elapsed * 0.32;
 this.position.set(8 * Math.sin(angle), 0.8, 8 * (Math.cos(angle) - 1));
 this.getObjectByName('Fox').rotation.y = Math.PI / 2 + angle;
}

